-- Deepen curated interview questions across all 12 career categories.
-- Calibrated STAR rubrics and technical keyword matching provide practice signals ($0 AI cost).

insert into public.interview_questions (role_category, round, difficulty, question, expected_keywords, rubric, model_answer)
values
  -- Software & Web
  ('Software & Web', 'Behavioral', 'Mid', 'Describe a situation where you had a technical disagreement with a teammate on architecture or code design. How did you resolve it?', array['tradeoffs', 'benchmarks', 'team consensus', 'data driven', 'documentation']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'During a redesign of our state layer, a teammate preferred Redux while I advocated for TanStack Query with lightweight Zustand. I created a benchmark prototype showing bundle size, caching behavior, and server state decoupling. We reviewed tradeoffs together, agreed on TanStack Query, and reduced boilerplate by 40%.'),
  ('Software & Web', 'Technical', 'Junior', 'How do you prevent race conditions or duplicate submissions when a user rapidly clicks a form submit button?', array['debounce', 'disable button', 'idempotency key', 'optimistic lock', 'pending state']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I manage a loading or pending state in the UI to disable the submit button immediately upon click. On the network and server boundary, I attach an idempotency key so repeated requests with the same key return the cached outcome without re-executing mutations.'),
  ('Software & Web', 'Technical', 'Senior', 'How do you diagnose and eliminate an event loop blockage in a high-traffic Node.js service?', array['event loop', 'worker threads', 'profiling', 'async non blocking', 'offload sync operations']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I inspect event loop delay using clinic.js or node:perf_hooks. I identify synchronous CPU-heavy operations such as JSON parsing of massive payloads or crypto routines, and offload them to Worker Threads or streaming pipelines, keeping main loop latency under 10ms.'),

  -- AI & Data Science
  ('AI & Data Science', 'Behavioral', 'Mid', 'How do you communicate complex statistical model limitations and tradeoffs to non-technical business stakeholders?', array['business impact', 'false positives', 'confidence intervals', 'visualizations', 'tradeoffs']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'When deploying a fraud classification model, executive stakeholders wanted zero fraud. I presented precision-recall tradeoffs in terms of lost revenue versus customer friction using intuitive cost-matrix charts, achieving alignment on an operating threshold that protected 94% of revenue.'),
  ('AI & Data Science', 'Technical', 'Junior', 'How do you handle severe class imbalance in a classification dataset without distorting reality?', array['class weights', 'pr auc', 'stratified sampling', 'f1 score', 'resampling']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I avoid relying on accuracy alone. Instead I use PR-AUC and balanced F1-score as primary metrics, apply stratified train/validation splitting, adjust loss function class weights during training, and calibrate probability thresholds for decision making.'),
  ('AI & Data Science', 'Technical', 'Senior', 'What techniques do you employ to prevent hallucination and enforce structured output in LLM inference pipelines?', array['json schema', 'retrieval augmented generation', 'grounding', 'guardrails', 'temperature zero']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I constrain generation using strict JSON Schema validation, ground context via RAG with semantic reranking and cited provenance, set low temperature, and validate outputs against domain invariant schemas.'),

  -- Cloud & DevOps
  ('Cloud & DevOps', 'Behavioral', 'Mid', 'Describe an incident where a production service was degraded. How did you coordinate response under pressure?', array['incident commander', 'communication', 'triage', 'mitigation', 'blameless postmortem']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'When a database connection spike degraded user logins, I stepped in as incident commander. I created a dedicated status channel, rolled back a rogue background query, scaled read replicas, restored service within 14 minutes, and conducted a blameless postmortem.'),
  ('Cloud & DevOps', 'Technical', 'Junior', 'Explain the difference between Docker images and containers, and how multi-stage builds optimize production images.', array['immutable layers', 'running instance', 'multi stage', 'distroless', 'attack surface']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'An image is an immutable template of layers, while a container is an isolated running instance. Multi-stage builds separate compile-time tools from runtime assets, producing minimal distroless images that reduce container size by over 70% and reduce attack surface.'),
  ('Cloud & DevOps', 'Technical', 'Senior', 'How do you architect zero-downtime database schema migrations for a high-traffic table with hundreds of millions of rows?', array['expand and contract', 'lock timeout', 'concurrent index', 'backfill', 'dual write']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I use the expand-and-contract pattern: add nullable column or dual-write, create indexes with CONCURRENTLY, backfill historical data in bounded asynchronous chunks with low lock timeouts, switch application reads, and finally drop deprecated fields.'),

  -- Cybersecurity
  ('Cybersecurity', 'Behavioral', 'Mid', 'How do you handle developer pushback when security compliance controls slow down release velocity?', array['empathy', 'guardrails', 'automation in ci', 'developer experience', 'pragmatism']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I treat security as an enabler rather than a blocker. When developers felt static analysis was noisy, I audited false positives, integrated SARIF checks directly into PR comments with actionable fix snippets, reducing triage time by 60% while maintaining required compliance gates.'),
  ('Cybersecurity', 'Technical', 'Junior', 'What is Cross-Site Scripting (XSS) and what defensive layers prevent it in modern web applications?', array['content security policy', 'contextual encoding', 'httponly cookies', 'react jsx escaping', 'sanitization']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'XSS occurs when malicious scripts are injected into trusted websites. Defense requires defense-in-depth: framework contextual escaping (JSX), strict Content Security Policy (CSP) headers disallowing unsafe-inline, and HttpOnly/SameSite cookie attributes to protect session credentials.'),
  ('Cybersecurity', 'Technical', 'Senior', 'How do you secure serverless and containerized microservice architectures against lateral movement following initial compromise?', array['zero trust', 'mtls', 'least privilege iam', 'network policies', 'ephemeral credentials']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I apply a Zero Trust model: mutual TLS (mTLS) with SPIFFE/SPIRE identity for all service communication, strict Kubernetes NetworkPolicies blocking default pod-to-pod traffic, ephemeral IAM credentials via OIDC, and read-only container root filesystems.'),

  -- Mobile & Multiplatform
  ('Mobile & Multiplatform', 'Behavioral', 'Mid', 'Describe how you resolved an app store review rejection related to privacy or guidelines.', array['app store guidelines', 'privacy declaration', 'permissions', 'review notes', 'resolution']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'Our iOS build was rejected for requested background location permissions. I audited feature necessity and replaced continuous background location with foreground geofencing on demand. I submitted updated review notes with demo video, securing approval within 24 hours.'),
  ('Mobile & Multiplatform', 'Technical', 'Junior', 'How do you optimize mobile scroll performance and avoid dropped frames in large dynamic lists?', array['virtualized list', 'recycling', 'memoization', 'image caching', '60 fps']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I use virtualized list components (FlashList/FlatList) with fixed item heights, memoize row renderers, offload image decoding to native disk caches, and avoid inline function declarations inside renderItem to sustain 60 FPS.'),
  ('Mobile & Multiplatform', 'Technical', 'Senior', 'How do you architect a shared cross-platform codebase while allowing tailored native UI and platform capabilities?', array['clean architecture', 'platform channels', 'dependency injection', 'native bridges', 'code sharing']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I separate domain logic, repositories, and state models into platform-agnostic packages, declare clean interfaces for platform services (biometrics, push, sensors), and provide platform-specific implementations via native plugins or dependency injection.'),

  -- Game Dev & 3D
  ('Game Dev & 3D', 'Behavioral', 'Mid', 'Describe how you negotiated scope cuts when an ambitious 3D project was falling behind deadline.', array['core gameplay loop', 'prioritization', 'mvp', 'team alignment', 'tradeoffs']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'Ahead of an investor demo, our physics engine and procedural generation were incomplete. I facilitated a priority review focused on the core 30-second gameplay loop, deferred secondary generation features, polished the primary loop, and delivered a high-impact demo on schedule.'),
  ('Game Dev & 3D', 'Technical', 'Junior', 'Explain draw calls in rendering engines and how mesh instancing reduces GPU overhead.', array['draw calls', 'batching', 'gpu overhead', 'mesh instancing', 'vertex buffers']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'A draw call is a command from CPU to GPU to render an object. High draw calls bottleneck the CPU. Instanced rendering allows drawing thousands of identical meshes with unique transforms and color matrices in a single draw call, drastically cutting overhead.'),
  ('Game Dev & 3D', 'Technical', 'Senior', 'How do you design a spatial partitioning system for high-performance physics and frustum culling with thousands of entities?', array['bvh', 'octree', 'spatial hashing', 'frustum culling', 'cache coherence']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I implement a dynamic BVH (Bounding Volume Hierarchy) or spatial hash grid for uniform distribution. I align memory in contiguous arrays (SoA pattern) for cache coherence, allowing broadphase collision checks and frustum culling to run in parallel worker jobs.'),

  -- UI/UX & Product Design
  ('UI/UX & Product Design', 'Behavioral', 'Mid', 'How do you balance user experience aspirations with aggressive development timelines and technical constraints?', array['collaboration', 'design engineering alignment', 'mvp', 'tradeoffs', 'system tokens']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I partner directly with frontend engineers during early wireframing. Instead of building bespoke elements, I leverage existing design system primitives and agree on a phased release: ship core functional UX first, then iterate on micro-interactions in subsequent sprints.'),
  ('UI/UX & Product Design', 'Technical', 'Junior', 'What constitutes WCAG 2.2 Level AA color contrast compliance for text and UI components?', array['4.5 to 1', '3 to 1', 'normal text', 'large text', 'ui components']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'WCAG AA requires a minimum contrast ratio of 4.5:1 for normal body text against its background, and 3:1 for large text (18pt or 14pt bold) and essential graphical UI components like input borders and icon buttons.'),
  ('UI/UX & Product Design', 'Technical', 'Senior', 'How do you structure design tokens across themes, modes, and multi-brand platforms?', array['global tokens', 'semantic tokens', 'component tokens', 'dark mode', 'design tokens']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I organize a three-tier token architecture: Tier 1 Global (raw palette e.g. blue-500), Tier 2 Semantic (intent tokens e.g. color-surface-interactive), and Tier 3 Component (e.g. button-primary-bg). Themes and dark modes override only Tier 2, ensuring seamless scalability without breaking UI contracts.'),

  -- Product & Agile Leadership
  ('Product & Agile Leadership', 'Behavioral', 'Mid', 'How do you say "no" to a high-priority feature request from an executive or major client without damaging relationships?', array['empathy', 'strategic priorities', 'opportunity cost', 'data backed', 'roadmap visibility']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I listen with empathy to understand their underlying objective, validate the value, and present our current roadmap commitments alongside the opportunity cost of pausing ongoing initiatives. I offer alternative lightweight solutions or schedule the request for next quarter discovery.'),
  ('Product & Agile Leadership', 'Technical', 'Junior', 'How do you write effective User Stories with clear, testable Acceptance Criteria using Gherkin syntax?', array['user story', 'given when then', 'acceptance criteria', 'definition of done', 'value statement']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I write stories following "As a [role], I want [capability] so that [benefit]". For criteria, I use Given-When-Then (Gherkin): Given a user with an active roadmap, When they click Complete Task, Then XP is awarded and next task unlocks.'),
  ('Product & Agile Leadership', 'Technical', 'Senior', 'How do you establish North Star metrics and input drivers to align multidisciplinary engineering squads?', array['north star metric', 'input metrics', 'leading indicators', 'retention', 'kpi']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I identify a North Star that measures customer value delivered over time, decompose it into team-owned input metrics, and review them weekly in team dashboards.'),

  -- QA & Reliability
  ('QA & Reliability', 'Behavioral', 'Mid', 'How do you advocate for test automation and test coverage when engineers claim they lack time to write tests?', array['culture of quality', 'velocity', 'ci integration', 'regression prevention', 'shift left']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I demonstrate that writing automated tests accelerates development by cutting manual verification time in half. I pair with engineers to provide reusable test helpers and seed factories, integrating fast tests into pre-commit and CI workflows.'),
  ('QA & Reliability', 'Technical', 'Junior', 'Explain the Test Pyramid and why UI end-to-end tests should be fewer in number compared to unit tests?', array['test pyramid', 'unit tests', 'integration tests', 'e2e tests', 'execution time']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'The Test Pyramid advocates a broad base of fast, reliable unit tests, a middle layer of integration tests, and a small peak of end-to-end UI tests. E2E tests are slower to execute, more resource-intensive, and prone to environmental flakiness.'),
  ('QA & Reliability', 'Technical', 'Senior', 'How do you design a robust load and stress testing strategy to determine maximum concurrent user capacity?', array['load testing', 'stress testing', 'p95 latency', 'k6', 'bottleneck identification']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I model realistic user journeys using k6 or Locust, establish ramp-up and sustained load profiles, measure p95/p99 response latency and server CPU/memory, identify database connection saturation, and define safe operating capacity limits.'),

  -- FinTech & Web3
  ('FinTech & Web3', 'Behavioral', 'Mid', 'How do you balance financial regulatory compliance (KYC/AML) with friction-free user onboarding?', array['progressive kyc', 'risk tiering', 'compliance', 'friction reduction', 'fraud prevention']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I implement tiered progressive KYC. Users can browse and explore immediately with low deposit limits, while higher-volume trading or fiat withdrawals require document verification, maximizing onboarding conversion while maintaining regulatory compliance.'),
  ('FinTech & Web3', 'Technical', 'Junior', 'Why must financial software avoid IEEE 754 floating-point types for currency calculations, and what should be used instead?', array['floating point error', 'arbitrary precision', 'integer cents', 'bignumber', 'rounding errors']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'Floating-point arithmetic suffers from binary rounding errors, which causes balance drift. Financial systems represent monetary amounts as integer minor units (cents, satoshis) or use arbitrary-precision decimal libraries (BigNumber/BigDecimal).'),
  ('FinTech & Web3', 'Technical', 'Senior', 'What are reentrancy attacks in smart contracts and how do checks-effects-interactions and reentrancy guards prevent them?', array['reentrancy', 'checks effects interactions', 'reentrancy guard', 'state update before external call', 'smart contract security']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'Reentrancy occurs when an external contract call executes before the caller updates its internal state, allowing recursive re-entry. Prevention requires the Checks-Effects-Interactions pattern (updating balances before transferring funds) and OpenZeppelin ReentrancyGuard mutexes.'),

  -- Hardware & Robotics
  ('Hardware & Robotics', 'Behavioral', 'Mid', 'How do you coordinate design reviews between mechanical, electrical, and firmware engineering teams?', array['cross functional', 'interface control documents', 'cad reviews', 'traceability', 'risk analysis']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I establish clear Interface Control Documents (ICD) defining pinouts, power budgets, and physical envelopes. We conduct structured 3D CAD/PCB overlap reviews before board fabrication, ensuring thermal dissipation and connector clearances are agreed upon.'),
  ('Hardware & Robotics', 'Technical', 'Junior', 'Compare I2C, SPI, and UART communication protocols in terms of speed, pin count, and reliability.', array['clock line', 'master slave', 'throughput', 'bus contention', 'pull up resistors']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'UART is asynchronous peer-to-peer using 2 pins. I2C uses 2 pins (SDA/SCL) with open-drain pull-ups supporting multiple addressed devices at moderate speeds. SPI is full-duplex synchronous using 4+ pins (MOSI, MISO, SCK, CS) providing higher data throughput for displays and flash memory.'),
  ('Hardware & Robotics', 'Technical', 'Senior', 'How do you implement fail-safe watchdog timers and crash recovery in real-time embedded systems?', array['watchdog timer', 'interrupt latency', 'brownout detection', 'safe state', 'reboot telemetry']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I configure hardware watchdog timers requiring servicing from the lowest-priority thread to verify scheduler health. Upon timeout or brownout reset, hardware actuators are driven to passive fail-safe states, and crash dumps are logged to non-volatile flash for postmortem analysis.'),

  -- Enterprise & Applied Tech
  ('Enterprise & Applied Tech', 'Behavioral', 'Mid', 'How do you handle technical debt in legacy enterprise systems while continuing to deliver new business capabilities?', array['strangler fig pattern', 'incremental modernization', 'business case', 'risk mitigation', 'velocity']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I use the Strangler Fig pattern rather than high-risk big-bang rewrites. I build new microservices around legacy boundaries, incrementally routing capabilities to modern APIs. I frame debt remediation in business terms: reduced maintenance costs and faster feature delivery.'),
  ('Enterprise & Applied Tech', 'Technical', 'Junior', 'What is Single Sign-On (SSO) and how does SAML / OpenID Connect (OIDC) authenticate enterprise users?', array['identity provider', 'service provider', 'tokens', 'oauth oidc', 'security assertions']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'SSO allows users to authenticate once through a central Identity Provider. SAML exchanges signed XML assertions between IdP and Service Provider. OIDC builds on OAuth 2.0 using signed JSON Web Tokens (ID tokens) to verify user identity.'),
  ('Enterprise & Applied Tech', 'Technical', 'Senior', 'How do you implement Role-Based Access Control (RBAC) and Attribute-Based Access Control (ABAC) in multi-tenant enterprise software?', array['rbac', 'abac', 'least privilege', 'tenant isolation', 'policy engine']::text[], '{"situation":true,"task":true,"action":true,"result":true}'::jsonb, 'I define roles for coarse permissions and overlay ABAC policies (evaluating tenant ID, departmental department, and resource state). I enforce policies centrally using a policy engine and at the database boundary via Row Level Security.')
on conflict (role_category, question) where role_category is not null do nothing;

